create extension if not exists pgcrypto;
insert into public.permissions(permission_key,permission_name,description,resource,action) values
('medical_files:read','Medical Files — Read','View and retrieve authorized medical files','medical_files','read'),('medical_files:upload','Medical Files — Upload','Upload and associate medical files','medical_files','upload'),('medical_files:update','Medical Files — Update','Update medical file metadata and clinical artifacts','medical_files','update'),('medical_files:archive','Medical Files — Archive','Archive and restore medical files','medical_files','archive'),('medical_files:reassociate','Medical Files — Reassociate','Change patient association','medical_files','reassociate'),('medical_files:manage','Medical Files — Manage','Manage medical file storage and intake','medical_files','manage') on conflict(permission_key) do nothing;
create table if not exists public.medical_files(id uuid primary key default gen_random_uuid(),tenant_id uuid not null references public.master_tenants(id) on delete cascade,patient_id uuid references public.clinic_patients(id) on delete restrict,visit_id uuid references public.clinic_visit_sessions(id) on delete set null,parent_file_id uuid references public.medical_files(id) on delete set null,file_kind text not null default 'document',original_filename text not null,mime_type text,extension text,size_bytes bigint not null default 0 check(size_bytes>=0),checksum_sha256 text,storage_provider text not null default 'cloud' check(storage_provider in('cloud','local','hybrid')),storage_path text,storage_status text not null default 'pending' check(storage_status in('pending','available','processing','failed','archived')),availability jsonb not null default '{}'::jsonb,metadata jsonb not null default '{}'::jsonb,created_by uuid references public.clinic_users(id) on delete set null,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),archived_at timestamptz,archived_by uuid references public.clinic_users(id) on delete set null);
create index if not exists medical_files_tenant_patient_idx on public.medical_files(tenant_id,patient_id,created_at desc); create index if not exists medical_files_tenant_visit_idx on public.medical_files(tenant_id,visit_id,created_at desc);
create table if not exists public.medical_file_storage_locations(id uuid primary key default gen_random_uuid(),medical_file_id uuid not null references public.medical_files(id) on delete cascade,tenant_id uuid not null references public.master_tenants(id) on delete cascade,provider text not null check(provider in('cloud','clinic_local')),device_id uuid references public.tenant_devices(id) on delete set null,object_path text not null,checksum_sha256 text,size_bytes bigint not null default 0 check(size_bytes>=0),status text not null default 'pending' check(status in('pending','available','missing','failed','archived')),last_verified_at timestamptz,last_synced_at timestamptz,created_at timestamptz not null default now(),unique(medical_file_id,provider,device_id));
create index if not exists medical_file_storage_locations_tenant_idx on public.medical_file_storage_locations(tenant_id,provider,status);
create table if not exists public.medical_file_sync_events(id uuid primary key default gen_random_uuid(),medical_file_id uuid not null references public.medical_files(id) on delete cascade,tenant_id uuid not null references public.master_tenants(id) on delete cascade,device_id uuid references public.tenant_devices(id) on delete set null,direction text not null check(direction in('cloud_to_local','local_to_cloud')),status text not null check(status in('queued','running','completed','failed')),bytes_transferred bigint not null default 0,error_message text,created_at timestamptz not null default now(),completed_at timestamptz);
create table if not exists public.medical_file_annotations(id uuid primary key default gen_random_uuid(),medical_file_id uuid not null references public.medical_files(id) on delete cascade,tenant_id uuid not null references public.master_tenants(id) on delete cascade,created_by uuid references public.clinic_users(id) on delete set null,annotation_type text not null,payload jsonb not null,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.medical_file_measurements(id uuid primary key default gen_random_uuid(),medical_file_id uuid not null references public.medical_files(id) on delete cascade,tenant_id uuid not null references public.master_tenants(id) on delete cascade,created_by uuid references public.clinic_users(id) on delete set null,measurement_type text not null,value numeric,unit text,payload jsonb not null default '{}'::jsonb,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.medical_file_ai_results(id uuid primary key default gen_random_uuid(),medical_file_id uuid not null references public.medical_files(id) on delete cascade,tenant_id uuid not null references public.master_tenants(id) on delete cascade,provider text not null,model text,status text not null default 'completed',result jsonb not null,created_at timestamptz not null default now());
alter table public.tenant_devices add column if not exists capabilities jsonb not null default '{}'::jsonb; alter table public.tenant_devices add column if not exists agent_version text; alter table public.tenant_devices add column if not exists health_status text not null default 'unknown'; alter table public.tenant_devices add column if not exists last_sync_at timestamptz;
alter table public.medical_files enable row level security; alter table public.medical_file_storage_locations enable row level security; alter table public.medical_file_sync_events enable row level security; alter table public.medical_file_annotations enable row level security; alter table public.medical_file_measurements enable row level security; alter table public.medical_file_ai_results enable row level security;
create policy medical_files_select on public.medical_files for select to authenticated using(tenant_id=public.get_current_tenant_id() and public.has_effective_permission('medical_files:read')); create policy medical_files_insert on public.medical_files for insert to authenticated with check(tenant_id=public.get_current_tenant_id() and public.has_effective_permission('medical_files:upload')); create policy medical_files_update on public.medical_files for update to authenticated using(tenant_id=public.get_current_tenant_id() and(public.has_effective_permission('medical_files:update') or public.has_effective_permission('medical_files:archive') or public.has_effective_permission('medical_files:reassociate'))) with check(tenant_id=public.get_current_tenant_id());
create policy medical_file_storage_select on public.medical_file_storage_locations for select to authenticated using(tenant_id=public.get_current_tenant_id() and public.has_effective_permission('medical_files:read')); create policy medical_file_storage_manage on public.medical_file_storage_locations for all to authenticated using(tenant_id=public.get_current_tenant_id() and public.has_effective_permission('medical_files:manage')) with check(tenant_id=public.get_current_tenant_id() and public.has_effective_permission('medical_files:manage'));
create policy medical_file_sync_select on public.medical_file_sync_events for select to authenticated using(tenant_id=public.get_current_tenant_id() and public.has_effective_permission('medical_files:read')); create policy medical_file_sync_manage on public.medical_file_sync_events for all to authenticated using(tenant_id=public.get_current_tenant_id() and public.has_effective_permission('medical_files:manage')) with check(tenant_id=public.get_current_tenant_id() and public.has_effective_permission('medical_files:manage'));
create policy medical_file_annotations_select on public.medical_file_annotations for select to authenticated using(tenant_id=public.get_current_tenant_id() and public.has_effective_permission('medical_files:read')); create policy medical_file_annotations_manage on public.medical_file_annotations for all to authenticated using(tenant_id=public.get_current_tenant_id() and public.has_effective_permission('medical_files:update')) with check(tenant_id=public.get_current_tenant_id() and public.has_effective_permission('medical_files:update'));
create policy medical_file_measurements_select on public.medical_file_measurements for select to authenticated using(tenant_id=public.get_current_tenant_id() and public.has_effective_permission('medical_files:read')); create policy medical_file_measurements_manage on public.medical_file_measurements for all to authenticated using(tenant_id=public.get_current_tenant_id() and public.has_effective_permission('medical_files:update')) with check(tenant_id=public.get_current_tenant_id() and public.has_effective_permission('medical_files:update'));
create policy medical_file_ai_select on public.medical_file_ai_results for select to authenticated using(tenant_id=public.get_current_tenant_id() and public.has_effective_permission('medical_files:read')); create policy medical_file_ai_manage on public.medical_file_ai_results for all to authenticated using(tenant_id=public.get_current_tenant_id() and public.has_effective_permission('medical_files:update')) with check(tenant_id=public.get_current_tenant_id() and public.has_effective_permission('medical_files:update'));
insert into public.role_permissions(role_id,permission_id) select r.id,p.id from public.roles r cross join public.permissions p where p.permission_key='medical_files:read' and r.role_key in('clinic_admin','doctor','receptionist') on conflict do nothing; insert into public.role_permissions(role_id,permission_id) select r.id,p.id from public.roles r cross join public.permissions p where p.permission_key='medical_files:upload' and r.role_key in('clinic_admin','doctor','receptionist') on conflict do nothing; insert into public.role_permissions(role_id,permission_id) select r.id,p.id from public.roles r cross join public.permissions p where p.permission_key in('medical_files:update','medical_files:archive','medical_files:reassociate','medical_files:manage') and r.role_key='clinic_admin' on conflict do nothing;
insert into storage.buckets(id,name,public,file_size_limit) values('medical-files','medical-files',false,5368709120) on conflict(id) do update set public=false,file_size_limit=5368709120;
create policy medical_files_storage_select on storage.objects for select to authenticated using(bucket_id='medical-files' and split_part(name,'/',1)=public.get_current_tenant_id()::text and public.has_effective_permission('medical_files:read')); create policy medical_files_storage_insert on storage.objects for insert to authenticated with check(bucket_id='medical-files' and split_part(name,'/',1)=public.get_current_tenant_id()::text and public.has_effective_permission('medical_files:upload')); create policy medical_files_storage_update on storage.objects for update to authenticated using(bucket_id='medical-files' and split_part(name,'/',1)=public.get_current_tenant_id()::text and public.has_effective_permission('medical_files:update')) with check(bucket_id='medical-files' and split_part(name,'/',1)=public.get_current_tenant_id()::text); create policy medical_files_storage_delete on storage.objects for delete to authenticated using(bucket_id='medical-files' and split_part(name,'/',1)=public.get_current_tenant_id()::text and public.has_effective_permission('medical_files:archive'));